import{_ as e,o as s,c as o,a3 as r}from"./chunks/framework.BwzYn71E.js";const b=JSON.parse('{"title":"常规优先级架构（不是结构）","description":"","frontmatter":{"translationSource":{"title":"常规优先级架构（不是结构）","archivedAt":"2026-10-27","url":"https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=8Aa94f8lDPwQd8yIT0MD2Q","scope":"page"},"translationLang":"zh","head":[["link",{"rel":"canonical","href":"https://kokobird28144.github.io/endfield-skydoc/zh/conventional-priority-architectures"}],["link",{"rel":"alternate","hreflang":"en","href":"https://kokobird28144.github.io/endfield-skydoc/conventional-priority-architectures"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://kokobird28144.github.io/endfield-skydoc/zh/conventional-priority-architectures"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://kokobird28144.github.io/endfield-skydoc/conventional-priority-architectures"}]]},"headers":[],"relativePath":"zh/conventional-priority-architectures.md","filePath":"zh/page-8Aa94f8lDPwQd8yIT0MD2Q.md"}'),p={name:"zh/conventional-priority-architectures.md"};function i(t,a,l,c,n,d){return s(),o("div",null,[...a[0]||(a[0]=[r('<div class="logistics-content"><h1 id="常规优先级架构-不是结构" tabindex="-1">常规优先级架构（不是结构） <a class="header-anchor" href="#常规优先级架构-不是结构" aria-label="Permalink to &quot;常规优先级架构（不是结构）&quot;">​</a></h1><blockquote><p>源页面 ID：<code>8Aa94f8lDPwQd8yIT0MD2Q</code> ｜ <a href="https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=8Aa94f8lDPwQd8yIT0MD2Q" target="_blank" rel="noreferrer">在腾讯文档中打开</a></p></blockquote><p><span id="source-block-qeUyFTFv540Pj8s5z2kQzC"></span></p><h2 id="常规优先级" tabindex="-1">常规优先级 <a class="header-anchor" href="#常规优先级" aria-label="Permalink to &quot;常规优先级&quot;">​</a></h2><p>在不同位置的优先级可以混用以实现更多优先级层级。当然也可以多级优先级物流结构解决。常规优先级之间通常可以相互替换。</p><p><span id="source-block-mlwukQHgPBO54VVp05zSz0"></span></p><h3 id="仓库优先级" tabindex="-1">仓库优先级 <a class="header-anchor" href="#仓库优先级" aria-label="Permalink to &quot;仓库优先级&quot;">​</a></h3><p><span id="source-block-NtWSrl6BOEbKXLVaBXjCTS"></span></p><h4 id="空仓加压" tabindex="-1"><strong>空仓加压</strong> <a class="header-anchor" href="#空仓加压" aria-label="Permalink to &quot;**空仓加压**&quot;">​</a></h4><p><img src="/endfield-skydoc/logistics/src/assets/images/img-e107d022f2df1611.q90-31352a454e52364d.webp" alt="常规优先级架构（不是结构）"></p><p>空仓加压通过在高优先方向，使用比寻常更多的取货口，实现高优先从仓库取出物品更多</p><p>优点：其结构简单，在修改时不需要修改入仓前的产线部分，更易于添加模块。</p><p>缺点：由于取货口优先级的存在与不稳定性，无法保证高优先方向的取货口正常工作，有可能一直不出物料。加压过多后边际效应明显，取货口空间不足。高优先取货口过多，走线麻烦。</p><p><a href="/endfield-skydoc/zh/1-5-automatic-maximum-gross-production">1.5智能最大毛产</a></p><p><span id="source-block-PU8JOqEVFjZT88TUdCy6qR"></span></p><h4 id="满仓震荡" tabindex="-1"><strong>满仓震荡</strong> <a class="header-anchor" href="#满仓震荡" aria-label="Permalink to &quot;**满仓震荡**&quot;">​</a></h4><p><img src="/endfield-skydoc/logistics/src/assets/images/img-d77a1b82ac561f2c.q90-8a37714e0e2ebab2.webp" alt="常规优先级架构（不是结构）"></p><p>满仓震荡通过满仓检测+计时器+锁存断路器实现低优先输出，只有满仓后才会有一段时间（计时器）的高输出量（高电平）而不会空仓，否则低优先方向没有输出（低电平），可以保证高优先方向始终可以输出物品。</p><p>优点：结构统一可扩展；不需要考虑取货口优先级的不稳定。</p><p>缺点：添加模块也需要添加满仓震荡低优先结构，不方便；低优先结构之间无法区分优先级；依赖存货口优先级；在每次检测到爆仓前会有一小段时间出现爆仓减产，需要加压入库解决。</p><p><a href="/endfield-skydoc/zh/full-storage-oscillation-plan">1.6智能最大毛产</a></p><p><span id="source-block-EAjCnqNEuX5TFnRRMqCyTj"></span></p><h4 id="空满仓震荡" tabindex="-1">空满仓震荡 <a class="header-anchor" href="#空满仓震荡" aria-label="Permalink to &quot;空满仓震荡&quot;">​</a></h4><p>一种特殊的满仓震荡，通过满仓检测+空仓检测+锁存断路器组成，相比于满仓输出一段时间的高输出量，这种震荡会维持到空仓为止，相对满仓震荡周期更长。</p><p>相比满仓震荡优点：检测结构可以使用更少的物流元件；爆仓减产的影响更小可以忽略。</p><p>相比满仓震荡缺点：空仓检测又重新需要考虑取货口优先级的不稳定问题了。</p><p>参见 赫 在技术开发局中的群相册的图片</p><p><span id="source-block-wpW334zm3uFiqbaymwtwu8"></span></p><h3 id="仓库前优先级" tabindex="-1">仓库前优先级 <a class="header-anchor" href="#仓库前优先级" aria-label="Permalink to &quot;仓库前优先级&quot;">​</a></h3><p><span id="source-block-zCQhpg8Az6d7dBtqlv3ycQ"></span></p><h4 id="满仓溢流" tabindex="-1"><strong>满仓溢流</strong> <a class="header-anchor" href="#满仓溢流" aria-label="Permalink to &quot;**满仓溢流**&quot;">​</a></h4><p><img src="/endfield-skydoc/logistics/src/assets/images/img-d845857d448bfcb6.q90-4507487e69954545.webp" alt="常规优先级架构（不是结构）"></p><p>满仓溢流使产物在进入仓库前就可以分出优先级，避免了不稳定的仓库相关优先级，代价是必须在入库前造出优先级。</p><p>优点：使用的优先级都是稳定的，不需要考虑优先级不稳定；上下限可以更大，几乎没有边际效应；添加高优先的模块方便。</p><p>缺点：占地巨大，每个生产单元都需要一个溢流模块；需要重新研究入仓前的模块划分与压缩。</p><p><a href="/endfield-skydoc/zh/full-storage-overflow-compatible-with-1-5-automatic-gross-production">兼容1.5智能毛产的满仓溢流方案</a></p><p><span class="mark-grey">#言（暂时无人检查这一结论）<br> 需要指出的是，如果允许使用存货口优先级，并不是每个生产单元都需要一个溢流模块——不连接溢流模块的生产单元使用输入能力大于生产能力同时优先级更高的入库（例如赤铜精炼用双带连接两个优先级高于连接了溢流模块的赤铜精炼的存货口的存货口），连接溢流模块的生产单元使用优先级更低的入库。<br> 原理简介：通过kokobird的</span><a href="/endfield-skydoc/zh/2-6-empty-storage-full-storage-we-need-more-oversupply">2.6 空仓？满仓？我们需要更多的加压！</a><span class="mark-grey">所描述的入库竞争中我们知道当取货波形（取货的时间函数）在某时刻低于需要优先存入的存入波形（存入的时间函数）时需要优先存入的生产单元会错误地堆积产物，但如果使用“输入能力大于生产能力同时优先级更高的入库”就能在取货波形高于存入波形时将这些堆积产物入库——只要波动不击穿该生产单元的缓存，就能保证其产物完全入库。</span></p><p><span id="source-block-NdoI0MM1aeyFeix9zEe3CQ"></span></p><h4 id="空仓溢流" tabindex="-1">空仓溢流 <a class="header-anchor" href="#空仓溢流" aria-label="Permalink to &quot;空仓溢流&quot;">​</a></h4><p>空仓溢流是满仓溢流的变种，与息壤可以简单通过反应池实现优先回仓不同，类似赤铜块之类的东西并不方便优先回仓，那么就交换回仓后的产物与不回仓的产物。</p><p>相对满仓溢流的优点：提供另一种实现思路，在某种意义上简化了某些物品的优先级实现。</p><p>相对满仓溢流的缺点：高优先路径都不能经过仓库，添加模块更加困难。</p><p><span id="source-block-KUQGdcq4cAbeg5ZiVm830v"></span></p><h3 id="仓库后优先级" tabindex="-1">仓库后优先级 <a class="header-anchor" href="#仓库后优先级" aria-label="Permalink to &quot;仓库后优先级&quot;">​</a></h3><p><span id="source-block-N7wpQpcB2PvmZfp0tGr0Nx"></span></p><h4 id="简单溢流" tabindex="-1">简单溢流 <a class="header-anchor" href="#简单溢流" aria-label="Permalink to &quot;简单溢流&quot;">​</a></h4><p>简单溢流在仓库后产生优先级。直接的采用对每个取货口都使用一个优先级物流结构来实现优先级，并且确保取货口数量充足，对于原料来说其既可以是空仓的，也可以是满仓的，不过空仓才能达成正常的利用率。</p><p>优点：优先级严格，无需考虑仓库不稳定优先级。</p><p>缺点：占地大；对每个取货口都要做优先级，效率低。</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-6495d4ded2b49faa.jpeg" alt="常规优先级架构（不是结构）"></p><p><span id="source-block-BNBg7dgMA5g42ZnlcO4cEt"></span></p><h4 id="恒流溢流" tabindex="-1">恒流溢流 <a class="header-anchor" href="#恒流溢流" aria-label="Permalink to &quot;恒流溢流&quot;">​</a></h4><p>[太简单了没有图]</p><p>恒流溢流是简单溢流的变种，在其基础上添加取货口数量限制，保证取货口不增加不减少。</p><p>相对简单溢流的优点：布局更为固定。</p><p>相对简单溢流的缺点：限制更多，不易变动。</p><p><span id="source-block-g2syXYc9TTPD3TDaELvEZP"></span></p><h2 id="特殊的优先级关系" tabindex="-1">特殊的优先级关系 <a class="header-anchor" href="#特殊的优先级关系" aria-label="Permalink to &quot;特殊的优先级关系&quot;">​</a></h2><p><span id="source-block-2KOpd4h0lpe9FzNsZ8Hbqf"></span></p><h3 id="原料产物优先级关系" tabindex="-1">原料产物优先级关系 <a class="header-anchor" href="#原料产物优先级关系" aria-label="Permalink to &quot;原料产物优先级关系&quot;">​</a></h3><p><span id="source-block-p7XbL4osQRZseYq4UXGFDn"></span></p><h4 id="产物空仓震荡" tabindex="-1">产物空仓震荡 <a class="header-anchor" href="#产物空仓震荡" aria-label="Permalink to &quot;产物空仓震荡&quot;">​</a></h4><p><img src="/endfield-skydoc/logistics/src/assets/images/img-c275fe01f08dcc19.q90-f85b415e5997815e.webp" alt="常规优先级架构（不是结构）"></p><p>产物空仓震荡目的在于保证某一种物品不耗尽，这里的空仓指的是产物空而不空。本质上是优先保留原料，次优先转化为产物。</p><p>优点：保证目标不一直空仓。结构简单。</p><p>缺点：独特的优先级机制，不适用于其他优先级所对应的场合；产物归零频繁，有进一步加工需求时可能取不到足够物品；必要空仓检测，占地稍大。</p><p><a href="https://www.bilibili.com/video/BV1vxJq6UEao/?" target="_blank" rel="noreferrer">智能补货备菜产线</a></p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-48f858c33534d036.jpeg" alt="常规优先级架构（不是结构）"></p><p><span id="source-block-9KPGt2ZWb52zRgnQaxurpo"></span></p><h4 id="原料空仓震荡" tabindex="-1">原料空仓震荡 <a class="header-anchor" href="#原料空仓震荡" aria-label="Permalink to &quot;原料空仓震荡&quot;">​</a></h4><p><img src="/endfield-skydoc/logistics/src/assets/images/img-dc1a860e44d05fa0.q90-9ad4ffccfdd392fc.webp" alt="常规优先级架构（不是结构）"></p><p>原料空仓震荡与产物空仓震荡类似，不过空仓的是原料。原理上需要稍微说明，当原料过多时，从仓库输出大于回到仓库，有余的部分就被加工了；当原料不足时其总是走高优先，不会去加工；而传送回仓保证其不会一回仓就全部输出，保证其存在不为0的情况可以用。</p><p>优点：结构简单；不需要仓位检测，占取货口少。</p><p>缺点：震荡范围小，每10s一个周期一个取货口最多5个。增加震荡范围需要大量增加取货口。</p><p><span id="source-block-2xpIgEALoqCpplNqo7yTn8"></span></p><h4 id="限速定产" tabindex="-1">限速定产 <a class="header-anchor" href="#限速定产" aria-label="Permalink to &quot;限速定产&quot;">​</a></h4><p>限速定产通过计算得到产物的平均消耗速度，通过限速方式控制产物的生产速度近似于其消耗速度。本质是假定了输入充分多，生产约大于消耗速率的产物，是对高优先方向的模拟。</p><p>优点：暖机快，一开机就接近稳定态。</p><p>缺点：无法实现正常的优先级，就无法用于自配平。</p><p><span id="source-block-hvZ0AGS2NcA9LkaMs32paQ"></span></p><h3 id="优先消耗关系" tabindex="-1">优先消耗关系 <a class="header-anchor" href="#优先消耗关系" aria-label="Permalink to &quot;优先消耗关系&quot;">​</a></h3><p><span id="source-block-2AsLx49xwckIpYbW86vESE"></span></p><h4 id="优先消耗某种电池发电" tabindex="-1">优先消耗某种电池发电 <a class="header-anchor" href="#优先消耗某种电池发电" aria-label="Permalink to &quot;优先消耗某种电池发电&quot;">​</a></h4><p>待补充内容，一说「省去高消耗物品的爆仓检测，就能自然做到互切」，暂时理论缺乏。</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-a4abd54bf8334190.q90-58fa5d62cc05ad30.webp" alt="常规优先级架构（不是结构）"></p></div>',1)])])}const u=e(p,[["render",i]]);export{b as __pageData,u as default};
